// Malloc based on brk/sbrk or mmap (Standard library wrapper)
int* array = (int*)malloc(sizeof(int) * 50);

if (array == NULL) {
    // Handle ENOMEM or other failures
    exit(EXIT_FAILURE);
}

array[0] = 100;
free(array);

// Direct System Call Allocation (mmap)
// Used for large blocks, anonymous memory, or file mapping
void* mem_region = mmap(
    NULL,                     // Address hint
    4096 * 5,                 // 5 pages size
    PROT_READ | PROT_WRITE,   // Protection flags
    MAP_PRIVATE | MAP_ANONYMOUS,
    -1, 0
);

if (mem_region == MAP_FAILED) {
    perror("mmap error");
}

// Release the mapped memory
munmap(mem_region, 4096 * 5);

// Allocating via sbrk (Older method, modifies program break)
// Rarely used directly anymore
void* current_break = sbrk(0);
void* new_memory = sbrk(4096);

if (new_memory == (void*)-1) {
    // Failure
}
